import { useEffect, useMemo, useState, useCallback, memo } from 'react';
import {
  Box,
  Card,
  Stack,
  Typography,
  TextField,
  IconButton,
  List,
  ListItem,
  ListItemText,
  ListItemAvatar,
  Avatar,
  Chip,
  Tooltip,
  Button,
  Divider,
  Snackbar,
  Grid,
  InputAdornment,
} from '@mui/material';
import { alpha, useTheme } from '@mui/material/styles';
import { Icon } from '@iconify/react';
import axios, { endpoints } from 'src/utils/axios';
import { useAuthContext } from 'src/auth/hooks';
import { useTranslation } from 'react-i18next';

type Referral = {
  phone: string | null;
  full_name: string | null;
  date: string;
  bonus_given: boolean;
  sold: number;
};

const pretty = (n: number) => new Intl.NumberFormat('fr-HT').format(n);

const CopyButton = memo(
  ({
    text,
    onCopied,
    tooltipKey,
    icon = 'mdi:content-copy',
    sx,
  }: {
    text?: string;
    onCopied: (label: string) => void;
    tooltipKey: string;
    icon?: string;
    sx?: any;
  }) => {
    const { t } = useTranslation();
    const handle = useCallback(async () => {
      if (!text) return;
      await navigator.clipboard.writeText(text);
      onCopied(t(tooltipKey));
    }, [text, onCopied, t, tooltipKey]);

    return (
      <Tooltip title={t(tooltipKey)}>
        <IconButton onClick={handle} sx={sx}>
          <Icon icon={icon} width={20} />
        </IconButton>
      </Tooltip>
    );
  }
);
CopyButton.displayName = 'CopyButton';

function StatCard({
  icon,
  titleKey,
  subtitle,
  value,
}: {
  icon: string;
  titleKey: string;
  subtitle?: string;
  value: string;
}) {
  const theme = useTheme();
  const { t } = useTranslation();
  return (
    <Card
      sx={{
        p: 3,
        height: '100%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        border: `1px solid ${alpha(theme.palette.primary.main, 0.16)}`,
        background: alpha(theme.palette.primary.light, 0.08),
        backdropFilter: 'blur(4px)',
      }}
    >
      <Stack spacing={0.5}>
        <Stack direction="row" alignItems="center" spacing={1}>
          <Icon icon={icon} width={26} />
          <Typography variant="h6">{t(titleKey)}</Typography>
        </Stack>
        {subtitle && (
          <Typography variant="body2" color="text.secondary">
            {subtitle}
          </Typography>
        )}
      </Stack>
      <Typography variant="h3" color="primary">
        {value}
      </Typography>
    </Card>
  );
}

export default function AccountReferral() {
  const theme = useTheme();
  const { user } = useAuthContext();
  const { t } = useTranslation();

  const [refCode, setRefCode] = useState<string>(user?.ref_code || '');
  const [referrals, setReferrals] = useState<Referral[]>([]);
  const [currentBonusSold, setCurrentBonusSold] = useState<number>(0);
  const [copied, setCopied] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const currency = user?.currency_code;
  const link = useMemo(
    () => (refCode ? `${window.location.origin}/auth/register?code=${refCode}` : ''),
    [refCode]
  );

  useEffect(() => {
    (async () => {
      try {
        const { data } = await axios.get(endpoints.auth.referrals);
        if (data?.ref_code && data.ref_code !== refCode) setRefCode(data.ref_code);
        setReferrals(data?.referrals || []);
        setCurrentBonusSold(Number(data?.current_bonus_sold || 0));
      } finally {
        setLoading(false);
      }
    })();
  }, []); // eslint-disable-line

  const onCopied = useCallback((label: string) => setCopied(label), []);
  const totalReferrals = referrals.length;
  const totalSold = referrals.reduce((s, r) => s + (Number(r.sold) || 0), 0);
  const estimatedGain = referrals.filter((r) => r.bonus_given).length * 20;

  return (
    <Stack spacing={3}>
      {/* HERO */}
      <Card
        sx={{
          p: { xs: 2, sm: 3 },
          overflow: 'hidden',
          color: '#fff',
          position: 'relative',
          background: `linear-gradient(135deg, ${theme.palette.primary.main}, ${theme.palette.success.main})`,
          boxShadow: `0 12px 32px ${alpha(theme.palette.primary.main, 0.35)}`,
        }}
      >
        <Box
          sx={{
            position: 'absolute',
            right: -48,
            top: -48,
            width: 200,
            height: 200,
            borderRadius: '50%',
            background: alpha('#fff', 0.12),
            filter: 'blur(2px)',
          }}
        />
        <Stack direction="row" alignItems="center" spacing={1}>
          <Icon icon="solar:stars-bold-duotone" width={28} />
          <Typography variant="h6">{t('referral.hero_title')}</Typography>
        </Stack>

        <Grid container spacing={1.5} alignItems="center" sx={{ mt: 2 }}>
          <Grid item xs={12} sm>
            <TextField
              value={refCode}
              placeholder="—"
              fullWidth
              InputProps={{
                readOnly: true,
                startAdornment: (
                  <InputAdornment position="start">
                    <Icon icon="solar:ticket-sale-line-duotone" width={20} />
                  </InputAdornment>
                ),
              }}
            />
          </Grid>
          <Grid item xs="auto">
            <CopyButton
              text={refCode}
              onCopied={onCopied}
              tooltipKey="referral.copy_code"
              sx={{
                bgcolor: alpha('#000', 0.2),
                color: '#fff',
                '&:hover': { bgcolor: alpha('#000', 0.28) },
              }}
            />
          </Grid>
          <Grid item xs="auto">
            <CopyButton
              text={link}
              onCopied={onCopied}
              tooltipKey="referral.copy_link"
              icon="solar:link-linear"
              sx={{
                bgcolor: alpha('#000', 0.2),
                color: '#fff',
                '&:hover': { bgcolor: alpha('#000', 0.28) },
              }}
            />
          </Grid>
        </Grid>

        {!!link && (
          <Stack
            direction={{ xs: 'column', sm: 'row' }}
            spacing={1.5}
            alignItems="center"
            sx={{ mt: 1 }}
          >
            <Typography variant="body2" sx={{ opacity: 0.9, flex: 1, wordBreak: 'break-all' }}>
              <Icon
                icon="solar:share-linear"
                width={18}
                style={{ verticalAlign: 'middle', marginRight: 6 }}
              />
              {t('referral.link_label', { link })}
            </Typography>
            <Button
              onClick={() =>
                navigator.share
                  ? navigator.share({ url: link }).catch(() => onCopied(t('referral.copy_link')))
                  : onCopied(t('referral.copy_link'))
              }
              startIcon={<Icon icon="solar:share-circle-linear" width={20} />}
              variant="contained"
              color="secondary"
              sx={{ color: '#fff' }}
            >
              {t('common.share')}
            </Button>
          </Stack>
        )}

        <Typography variant="body2" sx={{ mt: 1, opacity: 0.9 }}>
          {t('referral.hero_caption')}
        </Typography>
      </Card>

      {/* STATS */}
      <Grid container spacing={3}>
        <Grid item xs={12} md={4}>
          <StatCard
            icon="solar:wallet-money-bold-duotone"
            titleKey="referral.stat_estimated_title"
            subtitle={t('referral.referrals_count', { count: totalReferrals })}
            value={`${pretty(estimatedGain)} ${currency}`}
          />
        </Grid>
        <Grid item xs={12} md={4}>
          <StatCard
            icon="solar:coins-stacked-bold-duotone"
            titleKey="referral.stat_bonus_title"
            subtitle={t('referral.stat_bonus_sub')}
            value={`${pretty(currentBonusSold)} ${currency}`}
          />
        </Grid>
        <Grid item xs={12} md={4}>
          <StatCard
            icon="solar:cart-large-2-bold-duotone"
            titleKey="referral.stat_sales_title"
            subtitle={t('referral.stat_sales_sub')}
            value={`${pretty(totalSold)} ${currency}`}
          />
        </Grid>
      </Grid>

      {/* LIST */}
      <Card sx={{ p: 0 }}>
        <Box sx={{ p: { xs: 2, sm: 3 }, pb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
          <Icon icon="solar:users-group-rounded-bold-duotone" width={24} />
          <Typography variant="h6">{t('referral.list_title')}</Typography>
          <Chip
            size="small"
            label={totalReferrals}
            sx={{ ml: 'auto', mr: 0, bgcolor: alpha(theme.palette.primary.main, 0.08) }}
          />
        </Box>
        <Divider />
        <List sx={{ py: 0 }}>
          {loading && (
            <Box sx={{ p: 3, opacity: 0.7 }}>
              <Typography variant="body2">{t('common.loading')}</Typography>
            </Box>
          )}

          {!loading && referrals.length === 0 && (
            <Box sx={{ p: 3, display: 'flex', alignItems: 'center', gap: 1 }}>
              <Icon icon="solar:inbox-line-duotone" width={22} />
              <Typography variant="body2" color="text.secondary">
                {t('referral.empty')}
              </Typography>
            </Box>
          )}

          {referrals.map((r, i) => {
            const ok = Boolean(r.bonus_given);
            const title = r.full_name || r.phone || '—';
            return (
              <Box key={`${r.phone || 'n'}-${i}`}>
                <ListItem
                  sx={{
                    py: 1.5,
                    px: { xs: 2, sm: 3 },
                    '&:hover': { bgcolor: alpha(theme.palette.primary.main, 0.04) },
                  }}
                >
                  <ListItemAvatar>
                    <Avatar
                      sx={{
                        bgcolor: ok
                          ? alpha(theme.palette.success.main, 0.18)
                          : alpha(theme.palette.warning.main, 0.18),
                        color: ok ? theme.palette.success.main : theme.palette.warning.main,
                      }}
                    >
                      <Icon
                        icon={ok ? 'solar:check-circle-bold' : 'solar:hourglass-line-duotone'}
                        width={20}
                      />
                    </Avatar>
                  </ListItemAvatar>

                  <ListItemText
                    primary={
                      <Stack direction="row" alignItems="center" spacing={1} flexWrap="wrap">
                        <Typography variant="subtitle2">{title}</Typography>
                        <Chip
                          size="small"
                          variant="outlined"
                          color={ok ? 'success' : 'warning'}
                          label={t(ok ? 'referral.bonus_ok' : 'referral.bonus_wait')}
                          sx={{ height: 22 }}
                        />
                      </Stack>
                    }
                    secondary={
                      <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                        <Typography variant="caption" color="text.secondary">
                          <Icon
                            icon="solar:calendar-linear"
                            width={14}
                            style={{ marginRight: 6 }}
                          />
                          {r.date}
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                          •
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                          <Icon icon="solar:cart-linear" width={14} style={{ marginRight: 6 }} />
                          {t('referral.item_sold', {
                            amount: pretty(Number(r.sold) || 0),
                            currency,
                          })}
                        </Typography>
                      </Stack>
                    }
                  />

                  <CopyButton
                    text={r.phone ?? ''}
                    onCopied={onCopied}
                    tooltipKey="referral.copy_phone"
                    sx={{ ml: 1 }}
                  />
                </ListItem>
                {i < referrals.length - 1 && <Divider component="li" />}
              </Box>
            );
          })}
        </List>
      </Card>

      <Snackbar
        open={Boolean(copied)}
        autoHideDuration={1400}
        onClose={() => setCopied(null)}
        message={copied || ''}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      />
    </Stack>
  );
}
